  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "Cerivastatin absolute oral bioavailability was 60% (90% CI 51–70%) in healthy young men in a randomized crossover study vs IV, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C72"],
      "claim": "Dabrafenib absolute oral bioavailability was 95% (90% CI 81–110%) after a single 150 mg HPMC capsule dose in humans, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Safinamide absolute oral bioavailability was about 95% (90% CI 90–99%) for a 50 mg immediate-release tablet vs IV in healthy subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferred absolute oral bioavailability measurements are well above the 20% threshold, with values ranging from about 60% to 95%, and assay-transfer scores are high.",
  "evidence_gaps": [
    "No direct query-specific measurement is supplied; prediction relies on transferred evidence.",
    "Some records are qualitative or from special populations/conditions, but numeric absolute F values consistently exceed 20%.",
    "One trovafloxacin record reports a low RBA of 25%, but it is not an absolute bioavailability measurement and conflicts with multiple absolute F values."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

